-05-19T12:57:45.23484Z","shell.execute_reply":"2026-05-19T12:57:45.233361Z"}},"outputs":[{"data":{"text/html":["<ol class=list-inline>\n","\t<li>NA</li>\n","\t<li>'SEE'</li>\n","\t<li>'CB'</li>\n","\t<li>'NSC'</li>\n","\t<li>'SE'</li>\n","\t<li>'GD'</li>\n","\t<li>'AJG'</li>\n","\t<li>'CAT'</li>\n","\t<li>'ABT'</li>\n","\t<li>'SNI'</li>\n","</ol>\n"],"text/latex":["\\begin{enumerate*}\n","\\item NA\n","\\item 'SEE'\n","\\item 'CB'\n","\\item 'NSC'\n","\\item 'SE'\n","\\item 'GD'\n","\\item 'AJG'\n","\\item 'CAT'\n","\\item 'ABT'\n","\\item 'SNI'\n","\\end{enumerate*}\n"],"text/markdown":["1. NA\n","2. 'SEE'\n","3. 'CB'\n","4. 'NSC'\n","5. 'SE'\n","6. 'GD'\n","7. 'AJG'\n","8. 'CAT'\n","9. 'ABT'\n","10. 'SNI'\n","\n","\n"],"text/plain":[" [1] NA    \"SEE\" \"CB\"  \"NSC\" \"SE\"  \"GD\"  \"AJG\" \"CAT\" \"ABT\" \"SNI\""]},"metadata":{},"output_type":"display_data"}],"source":["##### Observations with Highest Residuals\n","test <- best.lm$residuals[order(best.lm$residuals, decreasing=TRUE)[1:10]]\n","t <-as.numeric(attributes(test)$names)\n","rez <- rep(NA, 10)\n","for(j in 1:10){\n","  rez[j] <- as.character(data[t[j],1])\n","}\n","rez"]},{"cell_type":"code","execution_count":14,"metadata":{"_cell_guid":"d83835c3-22ad-44bd-97b9-6a545eacca37","_uuid":"a200788b260bcec1e2d564c6b1c1445ef843dcb9","execution":{"iopub.execute_input":"2026-05-19T12:57:45.238611Z","iopub.status.busy":"2026-05-19T12:57:45.23727Z","iopub.status.idle":"2026-05-19T12:57:45.259825Z","shell.execute_reply":"2026-05-19T12:57:45.258687Z"}},"outputs":[],"source":["#NEXT: Undervalued Companies\n","udv <- predict(best.lm)-data$Market.Cap\n","frame.udv <- data.frame(data$Ticker.Symbol, data$Market.Cap, udv, data$Year)\n","undervalue <-subset(frame.udv, data.Year==2015)\n","names(undervalue) <- c(\"Ticker\", \"Market.Cap\",\"Total.Undervalue\", \"Year\")\n","\n","#Top Companies\n","fund <- subset(fund, For.Year==2015)\n","undervalue$Percent.Undervalue <- undervalue$Total.Undervalue/undervalue$Market.Cap"]},